package com.alexandev.afksandstone;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.GameObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class AfkSandstoneRockOverlay extends Overlay
{
	private final AfkSandstonePlugin plugin;
	private final AfkSandstoneConfig config;

	@Inject
	AfkSandstoneRockOverlay(AfkSandstonePlugin plugin, AfkSandstoneConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.highlightRocks()) return null;

		Color color = config.rockHighlightColor();
		g.setStroke(new BasicStroke(2f));

		for (GameObject rock : plugin.getActiveRocks())
		{
			Shape hull = rock.getConvexHull();
			if (hull == null) continue;
			g.setColor(color);
			g.draw(hull);
		}
		return null;
	}
}

package com.alexandev.afksandstone;

import com.google.inject.Provides;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.ObjectComposition;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "AFK Sandstone",
	description = "Tracks sandstone yield, grinder capacity, and sand production. Flashes the screen when mining stops or the inventory fills up, and outlines active sandstone rocks.",
	tags = {"mining", "sandstone", "sand", "desert", "quarry", "grinder", "afk", "skilling"}
)
public class AfkSandstonePlugin extends Plugin
{
	private static final Pattern[] GRINDER_PATTERNS = {
		// Drew dialog: "you've ground enough sandstone for X buckets of sand"
		Pattern.compile("ground\\s+enough\\s+sandstone\\s+for\\s+([\\d,]+)\\s+buckets?\\s+of\\s+sand",
			Pattern.CASE_INSENSITIVE),
		// Grinder machine: "The grinder is holding enough sandstone for X buckets of sand"
		Pattern.compile("grinder\\s+is\\s+holding\\s+enough\\s+sandstone\\s+for\\s+([\\d,]+)\\s+buckets?\\s+of\\s+sand",
			Pattern.CASE_INSENSITIVE),
		// Fallback: any "for X buckets of sand" phrasing
		Pattern.compile("for\\s+([\\d,]+)\\s+buckets?\\s+of\\s+sand",
			Pattern.CASE_INSENSITIVE),
	};

	@Inject private Client client;
	@Inject private OverlayManager overlayManager;
	@Inject private AfkSandstonePanelOverlay panel;
	@Inject private AfkSandstoneFlashOverlay flash;
	@Inject private AfkSandstoneRockOverlay rocks;
	@Inject private AfkSandstoneConfig config;

	private final Set<GameObject> activeRocks = new HashSet<>();

	private boolean wasMining;
	private int lastMiningTick;
	private int lastInvYield = -1;

	long sessionStart;
	int invSandstone;
	int invSand;
	int invYield;
	int sessionYield;
	int grinderCapacity;

	Set<GameObject> getActiveRocks() { return activeRocks; }

	@Override
	protected void startUp()
	{
		overlayManager.add(panel);
		overlayManager.add(flash);
		overlayManager.add(rocks);
		sessionStart = System.currentTimeMillis();
		invSandstone = 0;
		invSand = 0;
		invYield = 0;
		sessionYield = 0;
		lastInvYield = -1;
		grinderCapacity = 0;
		wasMining = false;
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(panel);
		overlayManager.remove(flash);
		overlayManager.remove(rocks);
		flash.reset();
		activeRocks.clear();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned e)
	{
		GameObject go = e.getGameObject();
		if (isSandstoneRock(go.getId()))
		{
			activeRocks.add(go);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned e)
	{
		activeRocks.remove(e.getGameObject());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState s = e.getGameState();
		if (s == GameState.LOADING || s == GameState.HOPPING || s == GameState.LOGIN_SCREEN)
		{
			activeRocks.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		Player me = client.getLocalPlayer();
		if (me != null)
		{
			if (isMining(me.getAnimation()))
			{
				wasMining = true;
				lastMiningTick = client.getTickCount();
			}
			else if (wasMining && client.getTickCount() - lastMiningTick >= config.idleTicks())
			{
				wasMining = false;
				if (config.flashOnIdle()) flash.trigger();
			}
		}

		// scan NPC/player dialog widgets (Drew and similar) once per tick
		scanDialogWidget(231); // DIALOG_NPC
		scanDialogWidget(217); // DIALOG_PLAYER
		scanDialogWidget(229); // DIALOG_SPRITE
	}

	@SuppressWarnings("deprecation")
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		if (e.getContainerId() != InventoryID.INV) return;
		ItemContainer inv = e.getItemContainer();
		if (inv == null) return;

		Item[] items = inv.getItems();

		int s1 = count(items, ItemID.SANDSTONE_1KG);
		int s2 = count(items, ItemID.SANDSTONE_2KG);
		int s5 = count(items, ItemID.SANDSTONE_5KG);
		int s10 = count(items, ItemID.SANDSTONE_10KG);

		invSandstone = s1 + s2 + s5 + s10;
		invYield = s1 * 1 + s2 * 2 + s5 * 4 + s10 * 8;
		invSand = count(items, ItemID.BUCKET_OF_SAND);

		if (lastInvYield >= 0 && invYield > lastInvYield)
		{
			sessionYield += invYield - lastInvYield;
		}
		lastInvYield = invYield;

		if (config.flashOnInvFull() && isInventoryFull(items))
		{
			flash.trigger();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		tryParseGrinder(event.getMessage());
	}

	private boolean isSandstoneRock(int id)
	{
		ObjectComposition comp = client.getObjectDefinition(id);
		if (comp == null) return false;
		if (comp.getImpostorIds() != null && comp.getImpostor() != null)
		{
			comp = comp.getImpostor();
		}
		String name = comp.getName();
		return name != null && name.toLowerCase().startsWith("sandstone");
	}

	private void scanDialogWidget(int groupId)
	{
		Widget w = client.getWidget(groupId, 0);
		if (w == null) return;
		Widget[] children = w.getStaticChildren();
		if (children != null)
		{
			for (Widget c : children)
			{
				if (c != null && c.getText() != null) tryParseGrinder(c.getText());
			}
		}
		if (w.getText() != null) tryParseGrinder(w.getText());
	}

	private void tryParseGrinder(String text)
	{
		if (text == null) return;
		// Strip HTML tags and normalise whitespace (widget text may contain <br>, <col=..>)
		String clean = text.replaceAll("<[^>]+>", " ").replaceAll("\\s+", " ");
		for (Pattern p : GRINDER_PATTERNS)
		{
			Matcher m = p.matcher(clean);
			if (m.find())
			{
				try
				{
					grinderCapacity = Integer.parseInt(m.group(1).replace(",", ""));
					return;
				}
				catch (NumberFormatException ignored) {}
			}
		}
	}

	private static int count(Item[] items, int... ids)
	{
		int total = 0;
		for (Item it : items)
		{
			for (int id : ids)
			{
				if (it.getId() == id)
				{
					total += it.getQuantity();
					break;
				}
			}
		}
		return total;
	}

	private static boolean isInventoryFull(Item[] items)
	{
		int used = 0;
		for (Item it : items)
		{
			if (it.getId() > 0) used++;
		}
		return used >= 28;
	}

	private static boolean isMining(int anim)
	{
		switch (anim)
		{
			case AnimationID.HUMAN_MINING_BRONZE_PICKAXE:
			case AnimationID.HUMAN_MINING_IRON_PICKAXE:
			case AnimationID.HUMAN_MINING_STEEL_PICKAXE:
			case AnimationID.HUMAN_MINING_BLACK_PICKAXE:
			case AnimationID.HUMAN_MINING_MITHRIL_PICKAXE:
			case AnimationID.HUMAN_MINING_ADAMANT_PICKAXE:
			case AnimationID.HUMAN_MINING_RUNE_PICKAXE:
			case AnimationID.HUMAN_MINING_DRAGON_PICKAXE:
			case AnimationID.HUMAN_MINING_DRAGON_PICKAXE_PRETTY:
			case AnimationID.HUMAN_MINING_INFERNAL_PICKAXE:
			case AnimationID.HUMAN_MINING_3A_PICKAXE:
			case AnimationID.HUMAN_MINING_CRYSTAL_PICKAXE:
				return true;
			default:
				return false;
		}
	}

	@Provides
	AfkSandstoneConfig provideConfig(ConfigManager cm)
	{
		return cm.getConfig(AfkSandstoneConfig.class);
	}
}

package com.alexandev.afksandstone;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("afksandstone")
public interface AfkSandstoneConfig extends Config
{
	@ConfigItem(
		keyName = "flashOnIdle",
		name = "Flash on idle",
		description = "Flash the screen when mining stops"
	)
	default boolean flashOnIdle() { return true; }

	@ConfigItem(
		keyName = "flashOnInvFull",
		name = "Flash on full inventory",
		description = "Flash the screen when the inventory fills up"
	)
	default boolean flashOnInvFull() { return true; }

	@ConfigItem(
		keyName = "idleTicks",
		name = "Idle ticks",
		description = "Number of game ticks without mining before the idle flash triggers"
	)
	default int idleTicks() { return 5; }

	@Alpha
	@ConfigItem(
		keyName = "flashColor",
		name = "Flash color",
		description = "Color of the flash overlay"
	)
	default Color flashColor() { return new Color(255, 0, 0, 120); }

	@ConfigItem(
		keyName = "flashDurationMs",
		name = "Flash duration (ms)",
		description = "How long the flash lasts"
	)
	default int flashDurationMs() { return 1500; }

	@ConfigItem(
		keyName = "highlightRocks",
		name = "Highlight active rocks",
		description = "Outline sandstone rocks that are not depleted"
	)
	default boolean highlightRocks() { return true; }

	@Alpha
	@ConfigItem(
		keyName = "rockHighlightColor",
		name = "Rock outline color",
		description = "Color of the outline on active sandstone rocks"
	)
	default Color rockHighlightColor() { return new Color(0, 255, 0, 200); }
}

package com.alexandev.afksandstone;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class AfkSandstoneFlashOverlay extends Overlay
{
	private final Client client;
	private final AfkSandstoneConfig config;
	private long flashStart;

	@Inject
	AfkSandstoneFlashOverlay(Client client, AfkSandstoneConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	void trigger() { flashStart = System.currentTimeMillis(); }
	void reset() { flashStart = 0; }

	@Override
	public Dimension render(Graphics2D g)
	{
		if (flashStart == 0) return null;
		long elapsed = System.currentTimeMillis() - flashStart;
		int duration = config.flashDurationMs();
		if (elapsed >= duration) { flashStart = 0; return null; }

		float progress = elapsed / (float) duration;
		float pulse = (float) Math.abs(Math.sin(progress * Math.PI * 3));
		float fade = 1f - progress;

		Color base = config.flashColor();
		int alpha = Math.max(0, Math.min(255, Math.round(base.getAlpha() * pulse * fade)));
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha));
		g.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		return null;
	}
}

package com.alexandev.afksandstone;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.text.NumberFormat;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class AfkSandstonePanelOverlay extends OverlayPanel
{
	private static final NumberFormat NF = NumberFormat.getInstance(Locale.US);

	private final AfkSandstonePlugin plugin;

	@Inject
	AfkSandstonePanelOverlay(AfkSandstonePlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("AFK Sandstone")
			.color(Color.ORANGE)
			.build());

		long minutes = Math.max(1, (System.currentTimeMillis() - plugin.sessionStart) / 60000);
		int sandInv = plugin.invYield + plugin.invSand;
		int sandPerHr = (int) (plugin.sessionYield * 60L / minutes);

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Sand (inv):")
			.right(String.valueOf(sandInv))
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Grinder:")
			.right(NF.format(plugin.grinderCapacity))
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Sand/hr:")
			.right(NF.format(sandPerHr))
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Time:")
			.right(minutes + " min")
			.build());

		return super.render(g);
	}
}
